import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));

/** Runtime configuration, overridable through environment variables. */
export const config = {
  /**
   * HTTP port for the API server.
   * Defaults to 4100 rather than Express' usual 3000/4000 to avoid clashing with the
   * other projects running on this machine. Override with the `PORT` env var.
   */
  port: Number(process.env.PORT ?? 4100),
  /** SQLite file. Generated by `npm run seed`; created automatically on first boot. */
  dbPath: process.env.DB_PATH ?? path.resolve(here, '..', 'data', 'neon-reel.sqlite'),
  /** Origin allowed to call the API in addition to the Vite dev server. */
  corsOrigins: (
    process.env.CORS_ORIGINS ?? 'http://localhost:5199,http://127.0.0.1:5199'
  )
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean),
} as const;
